module CSPRNG (  
    input clk,  
    input rst,  
    input [3:0] seed,  
    output reg [7:0] random_out  
);  
    reg [7:0] lfsr;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            lfsr <= {4'b0000, seed};  
            random_out <= 8'b0;  
        end else begin  
            lfsr <= {lfsr[6:0], lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3]};  
            random_out <= lfsr;  
        end  
    end  
endmodule

