    output reg random_bit  
);  
    reg [7:0] lfsr;  
    wire feedback;  

    assign feedback = lfsr[0] ^ lfsr[2] ^ lfsr[3] ^ lfsr[5]; // Taps for LFSR

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            lfsr <= seed;  
        end else begin  
            random_bit <= lfsr[0];  
            lfsr <= {lfsr[6:0], feedback};  
        end  
    end  
endmodule

