module watchdog_timer (
    input wire clk,
    input wire reset,
    input wire kick,
    output reg timeout
);
    parameter TIMEOUT_PERIOD = 4'b1111; // 15 clock cycles timeout period
    reg [3:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
            timeout <= 1'b0;
        end else if (kick) begin
            counter <= 4'b0000; // Reset counter on kick
            timeout <= 1'b0;
        end else if (counter < TIMEOUT_PERIOD) begin
            counter <= counter + 1;
            timeout <= 1'b0;
        end else begin
            timeout <= 1'b1; // Timeout condition
        end
    end
endmodule

