module watchdog_timer(
    input clk,
    input reset,
    output reg timeout,
    output reg [7:0] count
);
    parameter TIMEOUT_LIMIT = 8'd10; // Example timeout limit

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 8'd0;
            timeout <= 1'b0;
        end else if (count < TIMEOUT_LIMIT) begin
            count <= count + 1;
            timeout <= 1'b0;
        end else begin
            timeout <= 1'b1;
        end
    end
endmodule

