module serializer (
    input wire clk,
    input wire rst,
    input wire [7:0] data_in,
    input wire start,
    output reg tx
);
    reg [3:0] bit_counter;
    reg [7:0] shift_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 0;
            bit_counter <= 0;
            shift_reg <= 0;
        end else if (start) begin
            shift_reg <= data_in;
            bit_counter <= 0;
        end else if (bit_counter < 8) begin
            tx <= shift_reg[0];
            shift_reg <= {1'b0, shift_reg[7:1]};
            bit_counter <= bit_counter + 1;
        end else begin
            tx <= 0; // Hold low after transmission
        end
    end
endmodule

