module deserializer (
    input clk,
    input reset,
    input serial_in,
    output reg [15:0] parallel_out,
    output reg data_valid
);
    reg [3:0] bit_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            parallel_out <= 16'b0;
            data_valid <= 1'b0;
            bit_count <= 4'b0;
        end else if (bit_count < 16) begin
            parallel_out <= {serial_in, parallel_out[15:1]};
            bit_count <= bit_count + 1;
            if (bit_count == 15) begin
                data_valid <= 1'b1; // Set data valid when 16th bit is received
            end
        end
    end
endmodule

