module i2c_master (
    input clk,
    input reset,
    input start,
    input [7:0] data_in,
    output reg sda, // Serial Data Line
    output reg scl, // Serial Clock Line
    output reg ack // Acknowledge signal from slave
);

    reg [3:0] state;
    reg [3:0] bit_count;

    localparam IDLE = 4'd0,
               START = 4'd1,
               SEND_BYTE = 4'd2,
               WAIT_ACK = 4'd3,
               STOP = 4'd4;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            sda <= 1;
            scl <= 1;
            ack <= 0;
            bit_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= START;
                    end
                end
                START: begin
                    sda <= 0; // Start condition
                    state <= SEND_BYTE;
                    bit_count <= 0;
                end
                SEND_BYTE: begin
                    sda <= data_in[7 - bit_count]; // Send data bit
                    scl <= 0; // Clock low
                    state <= (bit_count == 7) ? WAIT_ACK : SEND_BYTE;
                    bit_count <= bit_count + 1;
                end
                WAIT_ACK: begin
                    scl <= 1; // Clock high
                    ack <= sda; // Read acknowledge from slave
                    state <= STOP;
                end
                STOP: begin
                    sda <= 1; // Stop condition
                    scl <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

