module uart_tx (
    input wire clk,              // System clock
    input wire rst,              // Reset signal
    input wire [7:0] data_in,    // 8-bit data input
    input wire start,            // Start transmission signal
    output reg tx,               // UART transmit output
    output reg busy              // Transmission busy flag
);

    parameter BAUD_RATE = 9600;
    parameter CLOCK_FREQ = 50000000;
    parameter BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] bit_index;         // Current bit index being transmitted
    reg [15:0] clk_count;         // Clock counter to handle bit timing
    reg [8:0] shift_reg;          // Shift register for data transmission

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1;              // Idle state is high
            busy <= 0;
            clk_count <= 0;
            bit_index <= 0;
            shift_reg <= 9'b111111111; // Reset shift register
        end else if (start && !busy) begin
            busy <= 1;
            shift_reg <= {1'b1, data_in, 1'b0}; // Start with start bit (0), then data, then stop bit (1)
            bit_index <= 0;
            clk_count <= 0;
        end else if (busy) begin
            if (clk_count < BIT_PERIOD - 1) begin
                clk_count <= clk_count + 1;
            end else begin
                clk_count <= 0;
                if (bit_index < 10) begin
                    tx <= shift_reg[0]; // Send the least significant bit
                    shift_reg <= {1'b1, shift_reg[8:1]}; // Shift right
                    bit_index <= bit_index + 1;
                end else begin
                    busy <= 0; // Transmission complete
                    tx <= 1;   // Set to idle state
                end
            end
        end
    end
endmodule

