module phase_detector (
    input clk,
    input clk_a,
    input clk_b,
    output reg [1:0] phase_error
);

    reg clk_a_last;
    reg clk_b_last;

    always @(posedge clk) begin
        clk_a_last <= clk_a;
        clk_b_last <= clk_b;

        if (clk_a_last && !clk_b_last) begin
            phase_error <= 2'b00; // clk_a is leading
        end else if (!clk_a_last && clk_b_last) begin
            phase_error <= 2'b10; // clk_a is lagging
        end else if (clk_a_last && clk_b_last) begin
            phase_error <= 2'b01; // clk_a and clk_b are in phase
        end
    end
endmodule

