module divide_by_8 (  
    input wire clk,  
    input wire reset,  
    output reg out  
);  
    reg [2:0] counter; // 3-bit counter to count from 0 to 7  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 3'b000;  
            out <= 0;  
        end else begin  
            if (counter == 3'b111) begin // When counter reaches 7  
                counter <= 3'b000;  
                out <= 1; // Output goes high every 8th clock cycle  
            end else begin  
                counter <= counter + 1;  
                out <= 0;  
            end  
        end  
    end  
endmodule

