module sr_latch (
    input wire S,
    input wire R,
    input wire clk,
    output reg Q,
    output reg Q_bar
);

always @(posedge clk) begin
    if (S && !R) begin
        Q <= 1'b1;
        Q_bar <= 1'b0;
    end else if (!S && R) begin
        Q <= 1'b0;
        Q_bar <= 1'b1;
    end else if (S && R) begin
        // Invalid state; hold previous state
        Q <= Q;
        Q_bar <= Q_bar;
    end
end

endmodule

