    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            control_signal <= 16'b0;  
            integral <= 16'b0;  
            previous_error <= 16'b0;  
        end else begin  
            integral <= integral + error;  
            control_signal <= (Kp * error) + (Ki * integral) + (Kd * (error - previous_error));  
            previous_error <= error;  
        end  
    end  
endmodule

